def solve(n: int, edges: List[List[int]]) -> int:
    union = list(range(n))

    def find(x: int) -> int:
        if union[x] != x:
            union[x] = find(union[x])
        return union[x]

    for u, v in edges:
        root_u, root_v = find(u), find(v)
        if root_u != root_v:
            union[root_v] = root_u

    return sum(1 for i in range(n) if i == find(i))

