def solve(nums):
    def binary_search(arr, l, r, x):
        if r < l:
            return -1
        if l == r:
            return arr[l]
        mid = l + (r - l) // 2
        if arr[mid] == arr[mid - 1] or arr[mid] == arr[mid + 1]:
            return arr[mid]
        if arr[mid] == mid + 1:
            return binary_search(arr, mid + 2, r, x)
        else:
            return binary_search(arr, l, mid - 1, x)

    nums = [0] + nums
    return binary_search(nums, 1, len(nums) - 1, len(nums) - 1)

